gIH(){return"\u0985\u09ac\u09b8\u09cd\u09a5\u09be\u09a8 \u098f\u09ac\u0982 \u0997\u09c1\u09a6\u09be\u09ae \u09aa\u09b0\u09bf\u099a\u09be\u09b2\u09a8\u09be \u0995\u09b0\u09c1\u09a8"},
gJ0(){return"\u09ae\u09be\u09b2\u09bf\u0995, \u09b9\u09bf\u09b8\u09be\u09ac\u09b0\u0995\u09cd\u09b7\u0995, \u09ac\u09be \u09b8\u09cd\u099f\u09be\u09ab/\u09a1\u09c7\u09b2\u09bf\u09ad\u09be\u09b0\u09bf \u09b9\u09bf\u09b8\u09be\u09ac\u09c7 \u099f\u09bf\u09ae \u09b8\u09a6\u09b8\u09cd\u09af \u09af\u09cb\u0997 \u0995\u09b0\u09c1\u09a8"},
gIS(){return"\u09aa\u09c1\u09b0\u09be\u09a4\u09a8 \u09b8\u09ab\u099f\u0993\u09af\u09bc\u09cd\u09af\u09be\u09b0 \u09a5\u09c7\u0995\u09c7 \u0987\u09ae\u09cd\u09aa\u09cb\u09b0\u09cd\u099f \u0995\u09b0\u09c1\u09a8"},
