gLQ(){return"\u09ac\u09cd\u09af\u09be\u0995\u0986\u09aa \u0993 \u09b8\u09bf\u0999\u09cd\u0995\u09c7\u09b0 \u099c\u09a8\u09cd\u09af \u09b8\u09b0\u09be\u09b8\u09b0\u09bf \u09ab\u09be\u0987\u09b2 \u0985\u09cd\u09af\u09be\u0995\u09cd\u09b8\u09c7\u09b8 \u09aa\u09cd\u09b0\u09af\u09bc\u09cb\u099c\u09a8 \u098f\u09ac\u0982 \u098f\u099f\u09bf \u098f\u0996\u09a8\u09cb \u0993\u09af\u09bc\u09c7\u09ac \u09ac\u09bf\u09b2\u09cd\u09a1\u09c7 \u0989\u09aa\u09b2\u09ac\u09cd\u09a7 \u09a8\u09af\u09bc\u0964 \u098f\u09b0 \u099c\u09a8\u09cd\u09af \u09ae\u09cb\u09ac\u09be\u0987\u09b2 \u09ac\u09be \u09a1\u09c7\u09b8\u09cd\u0995\u099f\u09aa \u0985\u09cd\u09af\u09be\u09aa \u09ac\u09cd\u09af\u09ac\u09b9\u09be\u09b0 \u0995\u09b0\u09c1\u09a8\u0964"},
gN7(){return"\u0995\u09cb\u09ae\u09cd\u09aa\u09be\u09a8\u09bf \u09aa\u09cd\u09b0\u09cb\u09ab\u09be\u0987\u09b2"},
gN1(){return"\u09b2\u09cb\u0997\u09cb \u09aa\u09b0\u09bf\u09ac\u09b0\u09cd\u09a4\u09a8 \u0995\u09b0\u09c1\u09a8"},
gMX(){return"\u09a0\u09bf\u0995\u09be\u09a8\u09be \u2014 \u09aa\u09cd\u09b0\u09a4\u09bf\u099f\u09bf \u099a\u09be\u09b2\u09be\u09a8\u09c7 \u09ae\u09c1\u09a6\u09cd\u09b0\u09bf\u09a4 \u09b9\u09af\u09bc"},
gMW(){return"\u098f\u099f\u09bf \u098f\u0995\u09ac\u09be\u09b0 \u09aa\u09c2\u09b0\u09a3 \u0995\u09b0\u09c1\u09a8 \u2014 \u098f\u099f\u09bf \u09a8\u09ae\u09c1\u09a8\u09be \u09b2\u09c7\u0986\u0989\u099f\u09c7\u09b0 \u09ae\u09a4\u09cb \u09aa\u09cd\u09b0\u09a4\u09bf\u099f\u09bf \u099a\u09be\u09b2\u09be\u09a8\u09c7 \u09ae\u09c1\u09a6\u09cd\u09b0\u09bf\u09a4 \u09b9\u09af\u09bc (\u09af\u09cb\u0997\u09be\u09af\u09cb\u0997\u09c7\u09b0 \u09ac\u09cd\u09af\u0995\u09cd\u09a4\u09bf, \u09ac\u09bf\u09b2\u09cd\u09a1\u09bf\u0982/\u09b0\u09be\u09b8\u09cd\u09a4\u09be/\u099c\u09cb\u09a8, \u09aa\u09bf\u0993 \u09ac\u0995\u09cd\u09b8, \u09b6\u09b9\u09b0, \u09a6\u09c7\u09b6)\u0964"},
gN0(){return"\u09ac\u09c7\u09b8 \u0995\u09be\u09b0\u09c7\u09a8\u09cd\u09b8\u09bf"},
