gN5(){return"\u09b6\u09ac\u09cd\u09a6\u09c7 \u09aa\u09b0\u09bf\u09ae\u09be\u09a3 \u09a6\u09c7\u0996\u09be\u09a8"},
gN6(){return"\u09ac\u09cd\u09af\u09be\u0982\u0995 \u09ac\u09bf\u09ac\u09b0\u09a3 \u09ac\u0995\u09cd\u09b8 \u09a6\u09c7\u0996\u09be\u09a8"},
gEu(){return"\u09b8\u0982\u09b0\u0995\u09cd\u09b7\u09bf\u09a4 \u09b9\u09af\u09bc\u09c7\u099b\u09c7\u0964"},
gGH(){return"\u09aa\u09c7\u099f\u09bf \u0995\u09cd\u09af\u09be\u09b6"},
